export{ModalCobroRapidoCtrl};function ModalCobroRapidoCtrl($scope,$uibModalInstance,mS,commonSvc,modalSvc,nombreModal,tS,fS,params){let{TIPO_DOC:TIPO_DOC,data:data}=params,{id:id,idTipoDocumento:idTipoDocumento}=data;$scope.data={},$scope.cobro={},$scope.cobro.valorCambio=0,$scope.entidadFinanciera={},$scope.banco={},$scope.cuentaBancaria={},$scope.estadoCobro={},$scope.findSubEntidad=function(id){$scope.entidadFinanciera=$scope.entidadesFinancieras.find(item=>item.idEntidadFinanciera===id),$scope.subEntidadesFinancieras=$scope.tempSubEntidadesFinancieras.filter(item=>item.idEntidadFinanciera===id),$scope.cobro.idSubEntidadFinanciera=$scope.subEntidadesFinancieras[0].idSubEntidadFinanciera},$scope.initiload=function(){try{showLoader();let query={tipo:2,idTipoDocumento:idTipoDocumento,idDocumento:id};mS.getData("get","CuentaPorCobrar/?json="+JSON.stringify(query),null,!0).then(response=>{let data=JSON.parse(response.payload);$scope.entidadesFinancieras=data[0];let idEntidadFinanciera=$scope.entidadesFinancieras.find(val=>"EFE"===val.codigo).idEntidadFinanciera;$scope.tempSubEntidadesFinancieras=data[1],$scope.bancos=data[2],$scope.ciudades=data[3],$scope.findSubEntidad(idEntidadFinanciera),hideLoader()}).catch(error=>{hideLoader(),console.log(error)})}catch(error){hideLoader(),console.log(error)}},$scope.initiload()}ModalCobroRapidoCtrl.$inject=["$scope","$uibModalInstance","mainService","commonService","modalService","nombreModal","toastService","formulario","params"];